import{f as r,o as i,c as n,aq as t}from"./chunks/framework.CAfuRaXs.js";const h=JSON.parse('{"title":"Naming Conventions für Workflows","description":"","frontmatter":{},"headers":[],"relativePath":"technik/naming_conventions/workflows.md","filePath":"technik/naming_conventions/workflows.md"}'),a={name:"technik/naming_conventions/workflows.md"};function l(o,e,s,c,d,u){return i(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="naming-conventions-fur-workflows" tabindex="-1">Naming Conventions für Workflows <a class="header-anchor" href="#naming-conventions-fur-workflows" aria-label="Permalink to &quot;Naming Conventions für Workflows&quot;">​</a></h1><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p>Es ist zu beachten, dass alle Workflows im Ordner <code>workflows</code> liegen müssen. Sie dürfen nicht auf unterordner aufgeteilt werden. Zur besseren Strukturierung in dem Ordner soll daher auf eine einheitliche Namenskonvention geachtet werden.</p></div><ul><li><code>callable-&lt;kurzbeschreibung&gt;.yml</code> ... <a href="https://docs.github.com/de/actions/using-workflows/reusing-workflows" target="_blank" rel="noreferrer">wiederverwendbare Workflows</a></li><li><code>dispatch-&lt;kurzbeschreibung&gt;.yml</code> ... <a href="https://docs.github.com/de/actions/using-workflows/manually-running-a-workflow" target="_blank" rel="noreferrer">manuell ausführbare workflows</a></li><li><code>&lt;service-name&gt;_&lt;trigger&gt;.yml</code> ... Workflows zu Jobs die durch ein bestimmtes Ereignis getriggert werden.</li><li><code>any-service_&lt;trigger&gt;-&lt;kurzbeschreibung&gt;.yml</code> ... Workflows, die unabhängig vom Service, bei einem bestimmten Ereignis ausgeführt werden</li></ul><h2 id="beispiele" tabindex="-1">Beispiele <a class="header-anchor" href="#beispiele" aria-label="Permalink to &quot;Beispiele&quot;">​</a></h2><h3 id="callable-kurzbezeichnung-yml" tabindex="-1"><code>callable-&lt;kurzbezeichnung&gt;.yml</code> <a class="header-anchor" href="#callable-kurzbezeichnung-yml" aria-label="Permalink to &quot;`callable-&lt;kurzbezeichnung&gt;.yml`&quot;">​</a></h3><p><code>callable-create-github-container-image.yml</code> beinhaltet einen wiederverwendbaren Workflow der ein Containerimage für Github erstellt.</p><h3 id="dispatch-kurzbeschreibung-yml" tabindex="-1"><code>dispatch-&lt;kurzbeschreibung&gt;.yml</code> <a class="header-anchor" href="#dispatch-kurzbeschreibung-yml" aria-label="Permalink to &quot;`dispatch-&lt;kurzbeschreibung&gt;.yml`&quot;">​</a></h3><p><code>dispatch-microservice-mvn-release.yml</code> ist ein Workflow, der manuell getriggert wird um ein Maven-Release eines Mikroservices durchzuführen.</p><h3 id="service-name-trigger-yml" tabindex="-1"><code>&lt;service-name&gt;_&lt;trigger&gt;.yml</code> <a class="header-anchor" href="#service-name-trigger-yml" aria-label="Permalink to &quot;`&lt;service-name&gt;_&lt;trigger&gt;.yml`&quot;">​</a></h3><p><code>wls-broadcast-service_push-dev-yml</code> ist der Workflow zum <code>wls-broadcast-service</code> der bei einem <code>push</code> auf <code>dev</code> ausgeführt wird.</p><p><code>doc_pull-request.yml</code> ist der Workflow zur Dokumentation, der bei einem <code>pull request</code> ausgeführt wird.</p><h3 id="any-service-ereignis-kurzbeschreibung-yml" tabindex="-1"><code>any-service_&lt;ereignis&gt;-&lt;kurzbeschreibung&gt;.yml</code> <a class="header-anchor" href="#any-service-ereignis-kurzbeschreibung-yml" aria-label="Permalink to &quot;`any-service_&lt;ereignis&gt;-&lt;kurzbeschreibung&gt;.yml`&quot;">​</a></h3><p><code>any-service_pull-request-dependency-review.yml</code> ist der Workflow zur Überprüfung der Lizenzen der Dependencies. Er wird bei jedem Pull Request ausgeführt.</p>',13)])])}const m=r(a,[["render",l]]);export{h as __pageData,m as default};
